out={}
for name,L in [("Videoigre",V),("Tehnologija i internet",T)]:
    res=[];seen=set()
    for i,(q,*o) in enumerate(L):
        n=' '.join(norm(q))
        assert len(set(o))==4,q
        if n in ex or n in seen: print('DUP',q); continue
        # near-dup check: high word overlap
        w=set(norm(q))
        for e in ex:
            ew=set(e.split())
            if len(w&ew)/max(1,len(w|ew))>0.6: print('NEAR',q,'~',e)
        seen.add(n)
        if len(q)>110: print('LONGQ',len(q),q)
        for x in o:
            if len(x)>30: print('LONGO',x)
        p=len(res)%4; o=list(o); o[0],o[p]=o[p],o[0]
        res.append({"q":q,"o":o,"a":p})
    out[name]=res
    print(name,len(res),[sum(1 for r in res if r['a']==k) for k in range(4)])
json.dump({"cats":out},open(base+'r2_09.json','w'),ensure_ascii=False,indent=1)
